接口名称:
// 使用 psts, 通过地址寄存器传入偏移,  用户可以选择更新偏移或者更新dst地址

void asc_storealign(__ubuf__ float *dst,  vector_bool src,  iter_reg  offset,   vector_bool mask)
void asc_storealign_pack(__ubuf__ float *dst,  vector_bool src,  iter_reg  offset,   vector_bool mask)

// 使用 psts, 偏移固定传入0， 由用户自行更新dst地址

void asc_storealign(__ubuf__ float *dst,  vector_bool src,   vector_bool mask)
void asc_storealign_pack(__ubuf__ float *dst,  vector_bool src,   vector_bool mask)

// 使用 psts, 通过int32_t 传入偏移,  用户可以选择更新偏移或者更新dst地址

void asc_storealign(__ubuf__ float *dst,  vector_bool src,  int32_t  offset,   vector_bool mask)
void asc_storealign_pack(__ubuf__ float *dst,  vector_bool src,  int32_t  offset,   vector_bool mask)

// 使用 psts, 通过int32_t 传入偏移，同时增加PostMode可以设置成硬件自动Post Update


void asc_storealign_postupdate(__ubuf__ float *dst,  vector_bool src,  int32_t  offset,   vector_bool mask)
void asc_storealign_pack_postupdate(__ubuf__ float *dst,  vector_bool src,  int32_t  offset,   vector_bool mask)
